export type WitnessAngularSuperProductivityPersistenceEvidence = {
	store: 'browser-indexed-db-through-localforage';
	databaseName: 'SUP';
	storeName: 'SUP_STORE';
	backend: 'none';
	stubbed: false;
	/** The driver localforage settled on, recorded rather than pinned. */
	driverInUse: string;
	keysBeforeJourney: string[];
	keysAfterJourney: string[];
	localStorageKeysBeforeJourney: string[];
	localStorageKeysAfterJourney: string[];
	survivesOnlineReload: true;
};

/**
 * The settled result of the task-list reorder, leg (b).
 *
 * The gesture is a genuine dragula pointer drag on the application's own task
 * list, and what the shape pins is a RULE rather than a measured order: the
 * task that moved is named, the rendered list before and after the move are
 * both recorded, the after-order is a permutation of the before-order — nothing
 * created or lost by moving one task — the order actually changed, and the
 * order the application's own store settled to matches the order the page
 * rendered. The literal titles and the from/to positions are measured by the
 * calibration driver and pinned when this proof is published; this shape
 * refuses a run whose store disagrees with its rendered list, or one that
 * dropped or duplicated a task while moving one, or one whose "after" order is
 * the "before" order unchanged.
 */
export type WitnessAngularSuperProductivityDrag = {
	state: 'measured-task-list-reorder';
	surface: (typeof WITNESS_REAL_APP_DRAG_SURFACES)[number];
	pointer: 'genuine-dragula-pointer-down-move-up';
	movedTask: string;
	renderedOrderBefore: string[];
	renderedOrderAfter: string[];
	storeOrderAfter: string[];
};

/**
 * The settled result of starting and stopping a task's timer, leg (c),
 * re-anchored after the u20c2j calibration contradicted the first shape.
 *
 * The anchor is the header's own global play button. Starting the timer through
 * it flips the button's `mat-icon` from `play_arrow` to `pause` and sets exactly
 * one current task; stopping it flips the icon back and clears the current task.
 * The shape pins the RULE the calibration measured on both lanes rather than the
 * literal icons: the before- and after-start icons differ (the flip), the
 * after-stop icon returns to the before-start icon (the round trip), starting
 * set one current task and stopping cleared it. The exact icon names are
 * recorded on {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TIME_TRACKING_REANCHOR}.
 *
 * The first shape carried two sub-rules the live application contradicted and
 * they are gone: it required a per-task `.play-icon-indicator` to be present,
 * and a `.time-val` carrying a digit. Both are recorded as truthful non-claims
 * on the re-anchor constant — the application's `ms-to-string` hides sub-minute
 * durations so a journey's `.time-val` is always `-`, and the per-task
 * `.start-task-btn` is hover-gated and never visible to a click, which is why
 * the timer is driven through the header rather than the task.
 */
export type WitnessAngularSuperProductivityTimeTracking = {
	state: 'measured-task-time-tracking';
	control: 'main-header .play-btn mat-icon';
	iconBeforeStart: string;
	iconAfterStart: string;
	iconAfterStop: string;
	currentTasksOnStart: number;
	currentTasksOnStop: number;
};

/**
 * The settled result of the settings-change, leg (d) — the last journey leg.
 *
 * Three measured parts, each a RULE rather than a pinned literal, because the
 * one lane-divergent part (the theme rgb) is a declared difference and the rest
 * is measured the same in both lanes:
 *
 *  - `projectSwitch`: the create grew the side-nav list by exactly one, and the
 *    switch flipped the current-project title to the project the create named —
 *    `currentTitleAfter` equals `newProjectTitle` and differs from
 *    `currentTitleBefore`. The literal titles are measured and travel, because
 *    they are the application's own and agree across lanes.
 *  - `theme`: the driven `huePrimary` mat-select change shifted the measured
 *    `styleVar` — `styleValueBefore` differs from `styleValueAfter`. The literal
 *    rgb values are per-lane and may differ (the declared lane difference on
 *    {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS}); the parity digest
 *    carries only the fact THAT the driven change shifted the var, not the value.
 *  - `shortcut`: `w` brought the work view — its host tag rendered after the
 *    press. The `b` non-claim is recorded on the settings constant.
 */
export type WitnessAngularSuperProductivitySettings = {
	state: 'measured-settings-change';
	projectSwitch: {
		control: string;
		dialog: string;
		titleControl: string;
		switchControl: string;
		newProjectTitle: string;
		currentTitleBefore: string;
		currentTitleAfter: string;
		projectCountBefore: number;
		projectCountAfter: number;
	};
	theme: {
		autoContrastControl: string;
		control: string;
		styleVar: string;
		styleValueBefore: string;
		styleValueAfter: string;
	};
	shortcut: {
		key: string;
		hostTag: string;
		hostTagPresentAfter: number;
	};
};

/**
 * The application-specific journey evidence.
 *
 * `typeface` and `persistence` are the facts legs (a) and (e) measure and are
 * always present. `drag` (leg b), `timeTracking` (leg c) and `settings` (leg d)
 * are the legs this journey drives: the parser requires all three once a browser
 * has driven the journey, but they are typed optional so a producer can populate
 * them without the not-yet-updated wiring failing to compile.
 */
export type WitnessAngularSuperProductivityJourney = {
	typeface: WitnessAngularSuperProductivityTypeface;
	persistence: WitnessAngularSuperProductivityPersistenceEvidence;
	drag?: WitnessAngularSuperProductivityDrag;
	timeTracking?: WitnessAngularSuperProductivityTimeTracking;
	settings?: WitnessAngularSuperProductivitySettings;
};

/**
 * The scroll reading, as a union rather than a pinned shape.
 *
 * This application pins a drawer container to the viewport and scrolls inner
 * panels, and it also renders long task lists; which of the two a route
 * actually produces is a measurement, and both outcomes are honest evidence.
 * What the schema refuses is a run that carries neither, and a lane pair that
 * disagrees about which one it is.
 */
export type WitnessAngularSuperProductivityScroll =
	| WitnessScrollSurface
	| WitnessMeasuredScrollAbsence;

export type WitnessAngularSuperProductivityRun = WitnessRealAppRun & {
	serviceWorker: WitnessAngularSuperProductivityServiceWorker;
	consoleErrorInventory: WitnessConsoleErrorInventory;
	failedRequestInventory: WitnessFailedRequestInventory;
	mockedNonLoopbackSeams: WitnessMockedNonLoopbackSeamInventory;
	renderedStyles: WitnessRenderedStyleEvidence;
	applicationJourney: WitnessAngularSuperProductivityJourney;
	scroll: WitnessAngularSuperProductivityScroll;
	behaviorDigest: string;
};

export type WitnessAngularSuperProductivityMutation = {
	failure: 'witness-semantic-assertion';
	intendedFailure: true;
	lane: 'baseline' | 'migrated';
	seam: string;
	path: string;
	offset: number;
	beforeSha256: string;
	mutatedSha256: string;
	afterRestoreSha256: string;
	restoredByteIdentically: true;
	restoredRun: 'pass';
	restoredBehaviorDigest: string;
};

export type WitnessAngularSuperProductivityReceipt = {
	schemaVersion: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SCHEMA;
	result: 'pass';
	fixture: typeof ANGULAR_SUPER_PRODUCTIVITY_FIXTURE;
	source: typeof ANGULAR_SUPER_PRODUCTIVITY_SOURCE;
	provenance: Record<string, unknown>;
	canonicalReceipts: typeof ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS;
	determinism: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_DETERMINISM;
	sassRandomBoundary: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SASS_RANDOM_BOUNDARY;
	runs: WitnessAngularSuperProductivityRun[];
	mutation: WitnessAngularSuperProductivityMutation;
	consoleErrors: Readonly<
		Record<'baseline' | 'migrated', readonly WitnessConsoleErrorInventoryEntry[]>
	>;
	failedRequests: Readonly<
		Record<'baseline' | 'migrated', readonly WitnessFailedRequestInventoryEntry[]>
	>;
	/**
	 * The exact per-lane seam membership as published. Both halves are held to
	 * the one shared declaration, because both emitted documents carry the same
	 * stylesheet link and a lane that asked for something else would mean the
	 * offline-faithful rebuild did not hold.
	 */
	mockedSeams: Record<'baseline' | 'migrated', WitnessMockedNonLoopbackSeamEntry[]>;
	fontSeam: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FONT_SEAM;
	serviceWorker: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER;
	/** What each lane's worker settled to, as its own runs measured it. */
	serviceWorkerParity: Record<
		'baseline' | 'migrated',
		{
			registeredScriptPath: string;
			scope: string;
			activeAtFinalCheckpoint: string;
			controlledAtFinalCheckpoint: boolean;
			cacheNames: string[];
		}
	>;
	migratedLaneChain: typeof ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN;
	migrationFindings: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MIGRATION_FINDINGS;
	typefaceDegradations: Record<
		'baseline' | 'migrated',
		WitnessAngularSuperProductivityTypeface
	>;
	renderedStyleParity: {
		state: 'measured-resolved-styles-with-declared-differences';
		probes: number;
		rule: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_DIFFERENCE_RULE;
		declaredDifferences: Array<{ label: string; why: string }>;
		otherProbesAgree: true;
	};
	persistence: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE;
	routeShape: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE;
	scroll: WitnessAngularSuperProductivityScroll;
	accommodations: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ACCOMMODATIONS;
	accommodationPayload: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ACCOMMODATION_PAYLOAD;
	dragSurface: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_DRAG_SURFACE;
	readiness: {
		angularLineage: { ready: number; total: number; counted: false };
		overall: { ready: number; total: number };
	};
	locality: {
		mode: 'offline';
		successfulNonLoopback: 0;
		osWideIsolation: false;
		mockedNonLoopbackSeams: number;
	};

	inspected.push({
		expected,
		receipt,
		journey,
		journeyRef,
		source: sourceIdentity(receipt),
		composition,
	});
}
if (
	aggregateByPath.size !==
	inspected.length +
		1 +
		(transaction.nextKilledByGoogleIntegrated ? 1 : 0) +
		(transaction.angularRealworldWitnessIntegrated ? 1 : 0) +
		(transaction.reactBoilerplateWitnessIntegrated ? 1 : 0) +
		(transaction.nextKilledByGoogleWitnessIntegrated ? 1 : 0) +
		(transaction.kind === 'react-avataaars-candidate' ||
		transaction.kind === 'react-calculator-candidate' ||
		transaction.kind === 'react-graphiql-013-candidate' ||
		transaction.kind === 'react-zero-sw-reconciliation' ||
		transaction.kind === 'react-papercups-browser-proof' ||
		transaction.kind === 'react-hospitalrun-browser-proof' ||
		transaction.kind === 'angular-factoriolab-browser-proof' ||
		transaction.kind === 'angular-jira-clone-browser-proof' ||
		transaction.kind === 'react-memos-browser-proof' ||
		transaction.kind === 'next-killedbygoogle-v3-browser-proof' ||
		transaction.kind === 'react-linkfree-browser-proof'
			? transaction.kind === 'react-zero-sw-reconciliation'
				? 2
				: transaction.kind === 'react-papercups-browser-proof'
					? 4
					: transaction.kind === 'react-hospitalrun-browser-proof'
						? 6
						: transaction.kind === 'angular-factoriolab-browser-proof'
							? 7
							: transaction.kind === 'angular-jira-clone-browser-proof'
								? 8
								: transaction.kind === 'react-memos-browser-proof'
									? 9
									: transaction.kind ===
										  'next-killedbygoogle-v3-browser-proof'
										? 10
										: transaction.kind ===
											  'react-linkfree-browser-proof'
											? 11
											: 1
			: 0)
)
	throw new Error('Aggregate contains an unknown or extra receipt');
const angularRealworld = await verifyAngularRealworldV15ToV16Evidence(root);
const angularRealworldWitness = transaction.angularRealworldWitnessIntegrated
	? await verifyWitnessAngularRealworldEvidence(root)
	: null;
const reactBoilerplateWitness = transaction.reactBoilerplateWitnessIntegrated
	? await verifyWitnessReactBoilerplateEvidence(root)
	: null;
const nextKilledByGoogleWitness = transaction.nextKilledByGoogleWitnessIntegrated
	? await verifyWitnessNextKilledByGoogleEvidence(root)
	: null;
/**
 * Which browser-proof lanes this transaction state carries.
 *
 * Each lane is admitted only above its own predecessor, so presence
 * cascades: a later state carries every earlier lane's rows. Deriving that
 * cascade once keeps every row, receipt-count and matrix check reading the
 * same answer instead of restating a longer disjunction at each use.
 */
const linkfreeIntegrated = transaction.kind === 'react-linkfree-browser-proof';
const killedbygoogleV3Integrated =
	transaction.kind === 'next-killedbygoogle-v3-browser-proof' || linkfreeIntegrated;
const memosIntegrated =
	transaction.kind === 'react-memos-browser-proof' || killedbygoogleV3Integrated;
const jiraCloneIntegrated =
	transaction.kind === 'angular-jira-clone-browser-proof' || memosIntegrated;
const factoriolabIntegrated =
	transaction.kind === 'angular-factoriolab-browser-proof' || jiraCloneIntegrated;
const hospitalrunIntegrated =
	transaction.kind === 'react-hospitalrun-browser-proof' || factoriolabIntegrated;
const papercupsIntegrated =
	transaction.kind === 'react-papercups-browser-proof' || hospitalrunIntegrated;
const papercups = papercupsIntegrated
	? await reactPapercupsConformanceRows(root, aggregateByPath)
	: null;
const hospitalrun = hospitalrunIntegrated
	? await reactHospitalrunConformanceRows(root, aggregateByPath)
	: null;
const factoriolab = factoriolabIntegrated
	? await angularFactoriolabConformanceRows(root, aggregateByPath)
	: null;
const jiraClone = jiraCloneIntegrated
	? await angularJiraCloneConformanceRows(root, aggregateByPath)
	: null;
const memos = memosIntegrated ? await reactMemosConformanceRows(root, aggregateByPath) : null;
const killedbygoogleV3 = killedbygoogleV3Integrated
	? await nextKilledbygoogleV3ConformanceRows(
			root,
			aggregateByPath,
			KILLED_BY_GOOGLE_PUBLISHED_SOURCE,
		)
	: null;
const linkfree = linkfreeIntegrated
	? await reactLinkfreeConformanceRows(root, aggregateByPath)
	: null;
if (transaction.kind === 'react-zero-sw-reconciliation' || papercupsIntegrated) {
	const migration = await verifyReceipt(REACT_BOILERPLATE_ZERO_SW_RECEIPT_PATH, {
		repositoryRoot: root,
	});
	const migrationMember = record(
		aggregateByPath.get(REACT_BOILERPLATE_ZERO_SW_RECEIPT_PATH),
		'React Boilerplate zero-SW migration aggregate fixture',
	);
	if (migrationMember.digest !== migration.digest)
		throw new Error('React Boilerplate zero-SW migration aggregate digest differs');
	const verified = await verifyWitnessReactBoilerplateZeroSwEvidence(root);
	const member = record(
		aggregateByPath.get(WITNESS_REACT_BOILERPLATE_ZERO_SW_RECEIPT_PATH),
		'React Boilerplate zero-SW aggregate fixture',
	);
	if (member.digest !== verified.digest)
		throw new Error('React Boilerplate zero-SW aggregate digest differs');
}
const nextKilledByGoogle = transaction.nextKilledByGoogleIntegrated
	? await verifyNextKilledByGoogleEvidence(root)
	: null;
if (transaction.kind === 'react-avataaars-candidate') {
	const verified = await verifyReactAvataaarsCompatibilityEvidence(root);
	const member = record(
		aggregateByPath.get(REACT_AVATAAARS_COMPATIBILITY_RECEIPT_PATH),
		'React Avataaars aggregate fixture',
	);
	if (member.digest !== verified.digest)
		throw new Error('React Avataaars aggregate digest differs');
}
if (transaction.kind === 'react-calculator-candidate') {
	const verified = await verifyReactCalculatorEvidence(root);
	const member = record(
		aggregateByPath.get(REACT_CALCULATOR_RECEIPT_PATH),
		'React Calculator aggregate fixture',
	);
	if (member.digest !== verified.digest)
		throw new Error('React Calculator aggregate digest differs');
}
if (transaction.kind === 'react-graphiql-013-candidate') {
	const verified = await verifyReactGraphiQL013Evidence(root);
	const member = record(
		aggregateByPath.get(REACT_GRAPHIQL_013_RECEIPT_PATH),
		'React GraphiQL aggregate fixture',
	);
	if (member.digest !== verified.digest)
		throw new Error('React GraphiQL aggregate digest differs');
}
if (nextKilledByGoogle && nextKilledByGoogle.digest !== nextKilledByGoogleDigest)
	throw new Error('Killed by Google aggregate digest differs');

const sourceGroups = new Map<string, typeof inspected>();
for (const item of inspected) {
	const key = canonicalize(item.source);
	const group = sourceGroups.get(key) ?? [];
	group.push(item);
	sourceGroups.set(key, group);
}
if (sourceGroups.size !== 2)
	throw new Error(
