161	 * lane's single Witness receipt, and the eighteen prior matrix cells plus the
162	 * factoriolab cell. This lane adds one receipt rather than two because its
163	 * three build-lane receipts are sealed inside the Witness receipt rather than
164	 * carried as separate aggregate members. No other transaction state is
165	 * affected by these counts.
166	 */
167	export const ANGULAR_FACTORIOLAB_TRUST_RECEIPTS = 21 as const;
168	export const ANGULAR_FACTORIOLAB_TRUST_MATRIX_CELLS = 19 as const;
169	
170	/**
171	 * Exact receipt and matrix-cell counts the jira-clone browser-proof transaction
172	 * pins for itself: the twenty-one factoriolab-state receipts plus this lane's
173	 * single Witness receipt, and the nineteen prior matrix cells plus the
174	 * jira-clone cell. Like factoriolab this lane adds one receipt rather than two,
175	 * because its four build-lane receipts are sealed inside the Witness receipt
176	 * rather than carried as separate aggregate members. No other transaction state
177	 * is affected by these counts.
178	 */
179	export const ANGULAR_JIRA_CLONE_TRUST_RECEIPTS = 22 as const;
180	export const ANGULAR_JIRA_CLONE_TRUST_MATRIX_CELLS = 20 as const;
181	
182	/**
183	 * Exact receipt and matrix-cell counts the memos browser-proof transaction pins
184	 * for itself: the twenty-two jira-clone-state receipts plus this lane's single
185	 * Witness receipt, and the twenty prior matrix cells plus the memos cell. The
186	 * lane adds one receipt rather than two because its build-lane receipt is
187	 * sealed inside the Witness receipt by the sha256 of its exact bytes rather
188	 * than carried as a separate aggregate member. No other transaction state is
189	 * affected by these counts.
190	 */
191	export const REACT_MEMOS_TRUST_RECEIPTS = 23 as const;
192	export const REACT_MEMOS_TRUST_MATRIX_CELLS = 21 as const;
193	
194	/**
195	 * Exact receipt and matrix-cell counts the killedbygoogle v3 browser-proof
196	 * transaction pins for itself: the twenty-three memos-state receipts plus this
197	 * lane's single Witness receipt, and the twenty-one prior matrix cells plus the
198	 * killedbygoogle v3 cell. Its two build-lane digests are sealed inside the
199	 * Witness receipt, so the lane adds one receipt rather than two. No other
200	 * transaction state is affected by these counts.
201	 */
202	export const NEXT_KILLEDBYGOOGLE_V3_TRUST_RECEIPTS = 24 as const;
203	export const NEXT_KILLEDBYGOOGLE_V3_TRUST_MATRIX_CELLS = 22 as const;
204	
205	/**
206	 * Exact receipt and matrix-cell counts the LinkFree browser-proof transaction
207	 * pins for itself: the twenty-four killedbygoogle-v3-state receipts plus this
208	 * lane's single Witness receipt, and the twenty-two prior matrix cells plus the
209	 * LinkFree cell. Its build-lane receipt is sealed inside the Witness receipt by
210	 * both canonical digest and exact bytes, so the lane adds one receipt rather
211	 * than two. No other transaction state is affected by these counts.
212	 */
213	export const REACT_LINKFREE_TRUST_RECEIPTS = 25 as const;
214	export const REACT_LINKFREE_TRUST_MATRIX_CELLS = 23 as const;
215	
216	/**
217	 * Verifies a retained build receipt through the browser proof that seals it.
218	 * A sealed build receipt is not a generic migration receipt, so it is verified
219	 * against the exact byte digest and canonical digest the Witness receipt binds,
220	 * and every artifact it references is re-hashed. Nothing here is asserted from
221	 * a literal: the returned digest and artifact count are measured.
222	 */
223	async function verifySealedBuildReceipt(
224		root: string,
225		label: string,
226		receiptPath: string,
227		sealed: { canonicalDigest: string; sha256: string },
228	): Promise<{ valid: true; digest: string; artifacts: number }> {
229		const bytes = await readFile(path.join(root, receiptPath));
230		if (sha256(bytes) !== sealed.sha256) throw new Error(`${label} build receipt bytes drifted`);
231		const receipt = asRecord(JSON.parse(bytes.toString('utf8')), `${label} build receipt`);
232		const integrity = asRecord(receipt.integrity, `${label} build receipt integrity`);
233		if (
234			integrity.algorithm !== 'sha256' ||
235			integrity.canonicalDigest !== sealed.canonicalDigest
236		)
237			throw new Error(`${label} build receipt integrity differs`);
238		if (!Array.isArray(receipt.artifacts))
239			throw new Error(`${label} build receipt artifacts are absent`);
240		for (const value of receipt.artifacts) {
241			const artifact = asRecord(value, `${label} build artifact`);
242			const artifactPath = asString(artifact.path, `${label} build artifact path`);
243			if (sha256(await readFile(path.join(root, artifactPath))) !== artifact.sha256)
244				throw new Error(`${label} build artifact digest mismatch: ${artifactPath}`);
245		}
246		return { valid: true, digest: sealed.canonicalDigest, artifacts: receipt.artifacts.length };
247	}
248	
249	export async function verifyReactPapercupsCanonicalReceipt(
250		rootDir: string,
251	): Promise<{ valid: true; digest: string; artifacts: number }> {
252		const root = path.resolve(rootDir);
253		const witness = await verifyWitnessReactPapercupsEvidence(root);
254		return verifySealedBuildReceipt(
255			root,
256			'React Papercups',
257			REACT_PAPERCUPS_RECEIPT_PATH,
258			witness.receipt.canonicalReceipt,
259		);
260	}
261	
262	export async function verifyReactHospitalrunCanonicalReceipt(
263		rootDir: string,
264	): Promise<{ valid: true; digest: string; artifacts: number }> {
265		const root = path.resolve(rootDir);
266		const witness = await verifyWitnessReactHospitalrunEvidence(root);
267		return verifySealedBuildReceipt(
268			root,
269			'React HospitalRun',
270			REACT_HOSPITALRUN_RECEIPT_PATH,
271			witness.receipt.canonicalReceipt,
272		);
273	}
274	
275	/**
276	 * The single receipt-verification dispatch shared by generation and
277	 * verification, so a receipt can never be verified one way when it is written
278	 * and another way when it is checked.
279	 */
280	export async function verifyTrustReceipt(
281		root: string,
282		receiptPath: string,
283	): Promise<{ digest: string; artifacts: number }> {
284		if (receiptPath === ANGULAR_REALWORLD_V15_TO_V16_RECEIPT.path)
285			return verifyAngularRealworldV15ToV16Evidence(root);
286		if (receiptPath === WITNESS_ANGULAR_REALWORLD_RECEIPT_PATH)
287			return verifyWitnessAngularRealworldEvidence(root);
288		if (receiptPath === WITNESS_REACT_BOILERPLATE_RECEIPT_PATH)
289			return verifyWitnessReactBoilerplateEvidence(root);
290		if (receiptPath === WITNESS_NEXT_KILLED_BY_GOOGLE_RECEIPT_PATH)
291			return verifyWitnessNextKilledByGoogleEvidence(root);
292		if (receiptPath === WITNESS_REACT_BOILERPLATE_ZERO_SW_RECEIPT_PATH)
293			return verifyWitnessReactBoilerplateZeroSwEvidence(root);
294		if (receiptPath === WITNESS_REACT_PAPERCUPS_RECEIPT_PATH)
295			return verifyWitnessReactPapercupsEvidence(root);
296		if (receiptPath === REACT_PAPERCUPS_RECEIPT_PATH)
297			return verifyReactPapercupsCanonicalReceipt(root);
298		if (receiptPath === WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH)
299			return verifyWitnessReactHospitalrunEvidence(root);
300		if (receiptPath === REACT_HOSPITALRUN_RECEIPT_PATH)
301			return verifyReactHospitalrunCanonicalReceipt(root);
302		if (receiptPath === WITNESS_ANGULAR_FACTORIOLAB_RECEIPT_PATH)
303			return verifyWitnessAngularFactoriolabEvidence(root);
304		if (receiptPath === WITNESS_ANGULAR_JIRA_CLONE_RECEIPT_PATH)
305			return verifyWitnessAngularJiraCloneEvidence(root);
306		if (receiptPath === WITNESS_REACT_MEMOS_RECEIPT_PATH)
307			return verifyWitnessReactMemosEvidence(root);
308		if (receiptPath === WITNESS_NEXT_KILLEDBYGOOGLE_V3_RECEIPT_PATH)
309			return verifyWitnessNextKilledbygoogleV3Evidence(root);
310		if (receiptPath === WITNESS_REACT_LINKFREE_RECEIPT_PATH)
311			return verifyWitnessReactLinkfreeEvidence(root);
312		if (receiptPath === NEXT_KILLED_BY_GOOGLE_RECEIPT_PATH)
313			return verifyNextKilledByGoogleEvidence(root, true);
314		if (receiptPath === REACT_AVATAAARS_COMPATIBILITY_RECEIPT_PATH)
315			return verifyReactAvataaarsCompatibilityEvidence(root);
316		if (receiptPath === REACT_CALCULATOR_RECEIPT_PATH)
317			return { ...(await verifyReactCalculatorEvidence(root)), artifacts: 5 };
318		if (receiptPath === REACT_GRAPHIQL_013_RECEIPT_PATH)
319			return verifyReactGraphiQL013Evidence(root);

